function parseThreshold(thresholdStr) {
  const match = thresholdStr.match(/^([a-z_]+)=([0-9]*\.?[0-9]+)$/);
  if (!match) {
    throw new Error(`Invalid threshold format: "${thresholdStr}". Use <metric>=<number>.`);
  }
  const [, metricId, minStr] = match;
  const min = parseFloat(minStr);
  if (min < 0 || min > 1) {
    throw new Error(`Threshold for "${metricId}" is ${min}, but must be between 0 and 1.`);
  }
  return { metricId, min };
}

function validateThresholds(thresholds, validMetricIds) {
  for (const { metricId } of thresholds) {
    if (!validMetricIds.includes(metricId)) {
      throw new Error(
        `Unknown metric "${metricId}". Valid metrics are: ${validMetricIds.join(', ')}.`
      );
    }
  }
}

function evaluateThresholds(evaluations, thresholds) {
  const results = [];
  for (const threshold of thresholds) {
    const metric = evaluations.find((m) => m.id === threshold.metricId);
    const score = metric?.score ?? null;
    const passed = score !== null && score >= threshold.min;
    results.push({
      metric: threshold.metricId,
      min: threshold.min,
      score,
      passed
    });
  }
  return results;
}

export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  thresholds = [],
  generatedAt = new Date().toISOString()
}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  let parsedThresholds = [];
  let thresholdResults = [];
  let passed = true;

  if (thresholds.length > 0) {
    const validMetricIds = evaluations.map((m) => m.id);
    parsedThresholds = thresholds.map((t) =>
      typeof t === 'string' ? parseThreshold(t) : t
    );
    validateThresholds(parsedThresholds, validMetricIds);
    thresholdResults = evaluateThresholds(evaluations, parsedThresholds);
    passed = thresholdResults.every((r) => r.passed);
  }

  const report = {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations
  };

  if (thresholds.length > 0) {
    report.passed = passed;
    report.thresholds = thresholdResults;
  }

  return report;
}

