      const status = threshold.passed ? 'PASS' : 'FAIL';
      const score = threshold.score !== null ? threshold.score : 'n/a';
      lines.push(`- **${threshold.metric}:** ${status} (min: ${threshold.min}, score: ${score})`);
    });
    lines.push('');
  }
  lines.push('---');
  lines.push('*Generated by FRAI Evaluation Harness*');
  return lines.join('\n');
}

