import fs from 'fs';
import path from 'path';

import {
  DEFAULT_METRICS,
  exactMatchMetric,
  lengthVarianceMetric,
  toxicityMetric
} from './metrics.js';
import { resolveReportPath, toJson, toMarkdown } from './reporters.js';

const defaultFs = fs;

const ensureArray = (value) => (Array.isArray(value) ? value : []);

export function loadDataset({ outputsPath, referencesPath, fs: fsModule = defaultFs } = {}) {
  if (!outputsPath) {
    throw new Error('outputsPath is required for evaluation.');
  }

  const outputsAbsolute = path.resolve(outputsPath);
  const outputsRaw = fsModule.readFileSync(outputsAbsolute, 'utf8');
  const outputs = JSON.parse(outputsRaw);

  let references = [];
  let referencesAbsolute = null;
  if (referencesPath) {
    referencesAbsolute = path.resolve(referencesPath);
    const referencesRaw = fsModule.readFileSync(referencesAbsolute, 'utf8');
    references = JSON.parse(referencesRaw);
  }

  return {
    outputs,
    references,
    outputsPath: outputsAbsolute,
    referencesPath: referencesAbsolute
  };
}

export function runEvaluations({
  outputs,
  references,
  metrics = DEFAULT_METRICS
} = {}) {
  const outs = ensureArray(outputs);
  const refs = ensureArray(references);

  const evaluations = metrics.map((metric) => {
    if (typeof metric === 'function') {
      return metric(outs, refs);
    }
    if (metric && typeof metric.evaluate === 'function') {
      return metric.evaluate(outs, refs);
    }
    throw new Error('Invalid metric supplied to runEvaluations.');
  });

  return evaluations;
}

function parseThreshold(thresholdStr) {
  const match = thresholdStr.match(/^([a-z_]+)=([0-9]*\.?[0-9]+)$/);
  if (!match) {
    throw new Error(`Invalid threshold format: "${thresholdStr}". Use <metric>=<number>.`);
  }
  const [, metricId, minStr] = match;
  const min = parseFloat(minStr);
  if (min < 0 || min > 1) {
    throw new Error(`Threshold for "${metricId}" is ${min}, but must be between 0 and 1.`);
  }
  return { metricId, min };
}

function normalizeThresholds(thresholds) {
  if (!thresholds || (Array.isArray(thresholds) && thresholds.length === 0)) {
    return [];
  }
  if (Array.isArray(thresholds)) {
    return thresholds.map((t) => (typeof t === 'string' ? parseThreshold(t) : t));
  }
  if (typeof thresholds === 'object') {
    return Object.entries(thresholds).map(([metricId, min]) => {
      if (typeof min !== 'number' || min < 0 || min > 1) {
        throw new Error(`Threshold for "${metricId}" is ${min}, but must be between 0 and 1.`);
      }
      return { metricId, min };
    });
  }
  return [];
}

function validateThresholds(thresholds, validMetricIds) {
  for (const { metricId } of thresholds) {
    if (!validMetricIds.includes(metricId)) {
      throw new Error(
        `Unknown metric "${metricId}". Valid metrics are: ${validMetricIds.join(', ')}.`
      );
    }
  }
}

function evaluateThresholds(evaluations, thresholds) {
  const results = [];
  for (const threshold of thresholds) {
    const metric = evaluations.find((m) => m.id === threshold.metricId);
    const score = metric?.score ?? null;
    const passed = score !== null && score >= threshold.min;
    results.push({
      metric: threshold.metricId,
      min: threshold.min,
      score,
      passed
    });
  }
  return results;
}

export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  thresholds,
  generatedAt = new Date().toISOString()
}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  let parsedThresholds = [];
  let thresholdResults = [];
  let passed = true;

  if (thresholds) {
    parsedThresholds = normalizeThresholds(thresholds);
    if (parsedThresholds.length > 0) {
      const validMetricIds = evaluations.map((m) => m.id);
      validateThresholds(parsedThresholds, validMetricIds);
      thresholdResults = evaluateThresholds(evaluations, parsedThresholds);
      passed = thresholdResults.every((r) => r.passed);
    }
  }

  const report = {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations
  };

  if (parsedThresholds.length > 0) {
    report.passed = passed;
    report.thresholds = thresholdResults;
  }

  return report;
}

export function writeReport({
  report,
  format = 'json',
  reportPath,
  fs: fsModule = defaultFs
}) {
  const resolved = resolveReportPath(reportPath, format);
  const payload = format === 'markdown' ? toMarkdown(report) : toJson(report);
  fsModule.writeFileSync(resolved, payload, 'utf8');
  return resolved;
}

export {
  DEFAULT_METRICS,
  exactMatchMetric,
  toxicityMetric,
  lengthVarianceMetric
};

export default {
  loadDataset,
  runEvaluations,
  generateReport,
  writeReport,
  DEFAULT_METRICS,
  exactMatchMetric,
  toxicityMetric,
  lengthVarianceMetric
};

