#!/usr/bin/env node
/**
 * Comprehensive test suite for the threshold feature
 * Tests all functionality required by the feature request
 */

import { generateReport, runEvaluations, writeReport } from '/private/tmp/100-tricks-runs/d49/without/h2-eval-thresholds/r5/packages/frai-core/src/eval/index.js';
import fs from 'fs';
import path from 'path';

let passCount = 0;
let failCount = 0;

function test(name, fn) {
  try {
    fn();
    console.log(`✓ ${name}`);
    passCount++;
  } catch (e) {
    console.error(`✗ ${name}`);
    console.error(`  ${e.message}`);
    failCount++;
  }
}

function testThrows(name, fn, expectedError) {
  try {
    fn();
    console.error(`✗ ${name} (should have thrown)`);
    failCount++;
  } catch (e) {
    if (expectedError && !e.message.match(expectedError)) {
      console.error(`✗ ${name} (wrong error: ${e.message})`);
      failCount++;
    } else {
      console.log(`✓ ${name}`);
      passCount++;
    }
  }
}

console.log('Testing Threshold Feature Implementation\n');

// Test 1: Basic threshold parsing and validation
console.log('1. Threshold Parsing & Validation');
test('Parse threshold string format', () => {
  const evaluations = runEvaluations({ outputs: ['test'], references: ['test'] });
  const report = generateReport({
    evaluations,
    outputsPath: '/tmp/out.json',
    referencesPath: '/tmp/ref.json',
    thresholds: ['exact_match=0.5']
  });
  if (!report.thresholds) throw new Error('No thresholds in report');
  if (report.thresholds[0].metric !== 'exact_match') throw new Error('Wrong metric');
  if (report.thresholds[0].min !== 0.5) throw new Error('Wrong min value');
});

test('Parse object format thresholds (SDK)', () => {
  const evaluations = runEvaluations({ outputs: ['test'], references: ['test'] });
  const report = generateReport({
    evaluations,
    outputsPath: '/tmp/out.json',
    referencesPath: '/tmp/ref.json',
    thresholds: { exact_match: 0.75 }
  });
  if (!report.thresholds) throw new Error('No thresholds in report');
  if (report.thresholds[0].min !== 0.75) throw new Error('Wrong min value');
});

testThrows('Reject invalid format', () => {
  const evaluations = runEvaluations({ outputs: ['test'], references: ['test'] });
  generateReport({
    evaluations,
    outputsPath: '/tmp/out.json',
    referencesPath: '/tmp/ref.json',
    thresholds: ['no_equals_sign']
  });
}, /Invalid threshold format/);

testThrows('Reject threshold > 1', () => {
  const evaluations = runEvaluations({ outputs: ['test'], references: ['test'] });
  generateReport({
    evaluations,
    outputsPath: '/tmp/out.json',
    referencesPath: '/tmp/ref.json',
    thresholds: ['exact_match=1.5']
  });
}, /must be between 0 and 1/);

testThrows('Reject threshold < 0', () => {
  const evaluations = runEvaluations({ outputs: ['test'], references: ['test'] });
  generateReport({
    evaluations,
    outputsPath: '/tmp/out.json',
    referencesPath: '/tmp/ref.json',
    thresholds: ['exact_match=-0.1']
  });
}, /must be between 0 and 1/);

testThrows('Reject unknown metric', () => {
  const evaluations = runEvaluations({ outputs: ['test'], references: ['test'] });
  generateReport({
    evaluations,
    outputsPath: '/tmp/out.json',
    referencesPath: '/tmp/ref.json',
    thresholds: ['unknown_metric=0.5']
  });
}, /Unknown metric/);

// Test 2: Threshold evaluation
console.log('\n2. Threshold Evaluation');
test('Passing threshold', () => {
  const evaluations = runEvaluations({ outputs: ['hello'], references: ['hello'] });
  const report = generateReport({
    evaluations,
    outputsPath: '/tmp/out.json',
    referencesPath: '/tmp/ref.json',
    thresholds: ['exact_match=0.5']
  });
  if (report.passed !== true) throw new Error('Should pass');
  if (!report.thresholds[0].passed) throw new Error('Threshold should pass');
});

test('Failing threshold', () => {
  const evaluations = runEvaluations({ outputs: ['hello', 'goodbye'], references: ['hello', 'world'] });
  const report = generateReport({
    evaluations,
    outputsPath: '/tmp/out.json',
    referencesPath: '/tmp/ref.json',
    thresholds: ['exact_match=0.9']
  });
  if (report.passed !== false) throw new Error('Should fail');
  if (report.thresholds[0].passed) throw new Error('Threshold should fail');
});

test('Multiple thresholds - all passing', () => {
  const evaluations = runEvaluations({ outputs: ['test'], references: ['test'] });
  const report = generateReport({
    evaluations,
    outputsPath: '/tmp/out.json',
    referencesPath: '/tmp/ref.json',
    thresholds: ['exact_match=0.5', 'length_variance=0.5']
  });
  if (report.passed !== true) throw new Error('Should pass');
  if (report.thresholds.length !== 2) throw new Error('Should have 2 thresholds');
  if (!report.thresholds.every(t => t.passed)) throw new Error('All thresholds should pass');
});

test('Multiple thresholds - one failing', () => {
  const evaluations = runEvaluations({ outputs: ['test'], references: ['test'] });
  const report = generateReport({
    evaluations,
    outputsPath: '/tmp/out.json',
    referencesPath: '/tmp/ref.json',
    thresholds: ['exact_match=0.5', 'length_variance=0.99']
  });
  if (report.passed !== false) throw new Error('Should fail');
  if (report.thresholds.every(t => t.passed)) throw new Error('Not all thresholds should pass');
});

test('Metric with no score fails threshold', () => {
  const evaluations = runEvaluations({ outputs: ['test'], references: [] });
  const report = generateReport({
    evaluations,
    outputsPath: '/tmp/out.json',
    referencesPath: '/tmp/ref.json',
    thresholds: ['exact_match=0.5']
  });
  if (report.passed !== false) throw new Error('Should fail');
  if (report.thresholds[0].score !== null) throw new Error('Score should be null');
  if (report.thresholds[0].passed) throw new Error('Should fail');
});

// Test 3: Report format
console.log('\n3. Report Format');
test('JSON report includes passed field', () => {
  const evaluations = runEvaluations({ outputs: ['test'], references: ['test'] });
  const report = generateReport({
    evaluations,
    outputsPath: '/tmp/out.json',
    referencesPath: '/tmp/ref.json',
    thresholds: ['exact_match=0.5']
  });
  if (typeof report.passed !== 'boolean') throw new Error('passed field missing');
  if (report.passed !== true) throw new Error('passed should be true');
});

test('JSON report includes thresholds list', () => {
  const evaluations = runEvaluations({ outputs: ['test'], references: ['test'] });
  const report = generateReport({
    evaluations,
    outputsPath: '/tmp/out.json',
    referencesPath: '/tmp/ref.json',
    thresholds: ['exact_match=0.5']
  });
  if (!Array.isArray(report.thresholds)) throw new Error('thresholds should be array');
  if (report.thresholds[0].metric !== 'exact_match') throw new Error('Missing metric field');
  if (report.thresholds[0].min !== 0.5) throw new Error('Missing min field');
  if (typeof report.thresholds[0].score !== 'number') throw new Error('Missing score field');
  if (typeof report.thresholds[0].passed !== 'boolean') throw new Error('Missing passed field');
});

test('Report without thresholds has no passed field', () => {
  const evaluations = runEvaluations({ outputs: ['test'], references: ['test'] });
  const report = generateReport({
    evaluations,
    outputsPath: '/tmp/out.json',
    referencesPath: '/tmp/ref.json'
  });
  if (report.passed !== undefined) throw new Error('Should not have passed field');
  if (report.thresholds !== undefined) throw new Error('Should not have thresholds field');
});

// Test 4: Markdown report
console.log('\n4. Markdown Report');
test('Markdown includes Thresholds section', () => {
  const tmpDir = '/tmp/frai-test-' + Date.now();
  fs.mkdirSync(tmpDir, { recursive: true });

  const evaluations = runEvaluations({ outputs: ['test'], references: ['test'] });
  const report = generateReport({
    evaluations,
    outputsPath: '/tmp/out.json',
    referencesPath: '/tmp/ref.json',
    thresholds: ['exact_match=0.5']
  });

  const markdownPath = writeReport({
    report,
    format: 'markdown',
    reportPath: path.join(tmpDir, 'report.md')
  });

  const content = fs.readFileSync(markdownPath, 'utf8');
  if (!content.includes('## Thresholds')) throw new Error('Missing Thresholds section');
  if (!content.includes('exact_match')) throw new Error('Missing metric name');
  if (!content.includes('PASS')) throw new Error('Missing result indicator');

  fs.rmSync(tmpDir, { recursive: true, force: true });
});

// Test 5: Backward compatibility
console.log('\n5. Backward Compatibility');
test('Existing reports unaffected', () => {
  const evaluations = runEvaluations({ outputs: ['test'], references: ['test'] });
  const report = generateReport({
    evaluations,
    outputsPath: '/tmp/out.json',
    referencesPath: '/tmp/ref.json'
  });
  if (!report.metadata) throw new Error('Missing metadata');
  if (!Array.isArray(report.metrics)) throw new Error('Missing metrics');
  if (report.passed !== undefined) throw new Error('Should not have passed field');
});

// Summary
console.log(`\n${'='.repeat(50)}`);
console.log(`Tests passed: ${passCount}`);
console.log(`Tests failed: ${failCount}`);
console.log(`${'='.repeat(50)}`);

if (failCount > 0) {
  process.exit(1);
}

console.log('\n✓ All comprehensive tests passed!');
console.log('\nImplementation Summary:');
console.log('✓ Threshold string parsing (metric=score)');
console.log('✓ Threshold object format (SDK)');
console.log('✓ Multiple thresholds support');
console.log('✓ Proper validation and error handling');
console.log('✓ JSON report format with passed and thresholds fields');
console.log('✓ Markdown report with Thresholds section');
console.log('✓ Backward compatibility preserved');
console.log('✓ Exit code logic ready (implemented in CLI)');

